pub fn document_color_capability() -> ColorProviderCapability {
    ColorProviderCapability::Simple(true)
}

/// 语句中的颜色字面量
///
/// # Arguments
/// * **scene_path** - 场景相对项目根的路径.
///
/// # Behavior
/// * 区间为 **UTF-8** 行列 (相对行首的字节偏移), 可直接交给
///   [`crate::encode::document_colors_utf8_to_utf16`] 转成 LSP 要求的 UTF-16 编码.
/// * 覆盖两类写法:
///   * 语句参数, 形如 `intro:全屏文字 -fontColor=rgba(0, 0, 0, 1);`
///   * 文本拓展样式, 形如 `角色A:[文字](style=color:#FF8800);`
/// * 取值解析不出的位置不报色块 (CSS 颜色名 `red` 等不在 [`Color`] 支持范围内).
pub fn document_color(scene_path: &str, project: &Project) -> Option<Vec<ColorInformation>> {
    let scene = project.resource().scene.get(scene_path)?.as_item()?;
    Some(
        color_literals(scene)
            .into_iter()
            .map(|literal| ColorInformation {
                range: literal_range(&literal),
                color: to_lsp_color(literal.color),
            })
            .collect(),
    )
}

/// 颜色修改建议
///
/// # Arguments
/// * **scene_path** - 场景相对项目根的路径.
/// * **span** - 待修改区间 (UTF-8 行列), 通常是本模块 [`document_color`] 报出的区间.
/// * **color** - 客户端取到的新颜色.
///
/// # Behavior
/// * 参数颜色按语句参数要求的 `rgba(R, G, B, A)` 生成, 改完仍是合法语句
///   (见 `webgal-language-core` 的 `parse_color_css_rgba`).
/// * 文本样式颜色用 hex 生成 (不透明 `#RRGGBB`, 有透明度 `#RRGGBBAA`) ——
///   样式取值里写不出 `)`, 而且 hex 能被重新识别成颜色字面量, 改完色块不会消失.
/// * 区间处没有颜色字面量时返回 `None`.
pub fn color_presentation(
    scene_path: &str,
    span: Range,
    color: lsp_types::Color,
    project: &Project,
) -> Option<Vec<ColorPresentation>> {
    let color = from_lsp_color(color);
    let scene = project.resource().scene.get(scene_path)?.as_item()?;
    let literals = color_literals(scene);
    let literal = literals
        .iter()
        .find(|literal| literal_range(literal) == span)
        .or_else(|| {
            literals
                .iter()
                .find(|literal| overlaps(&literal_range(literal), span))
        })?;

    let text = format_color(color, literal.syntax);
    Some(vec![ColorPresentation {
        label: text.clone(),
        text_edit: Some(TextEdit {
            range: literal_range(literal),
            new_text: text,
        }),
        additional_text_edits: None,
    }])
}

