/// 颜色参数
///
/// 这些参数在语句里声明为颜色 (见 `webgal-language-core` 的 `IntroSentence`),
/// 取值必须是 `rgba(R, G, B, A)`.
/// 参数名判定与语义高亮的参数名判定同源, 都按名字匹配, 不依赖语句类型.
const COLOR_ARGUMENTS: &[&str] = &["fontColor", "backgroundColor"];

/// 颜色字面量
#[derive(Debug, Clone)]
struct ColorLiteral {
    /// 行号 (从 0 开始)
    line: u32,
    /// 行内区间 (相对行首的字节偏移)
    span: ops::Range<usize>,
    color: Color,
    syntax: ColorSyntax,
}

/// 颜色字面量所在的语法位置
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ColorSyntax {
    /// 语句参数, 取值需为 `rgba(R, G, B, A)`
    Argument,
    /// 文本拓展样式, 取值是标准 CSS 行内颜色.
    ///
    /// 注意样式取值不能含 `)`: 文本拓展语法在 `](` 后的第一个 `)` 处结束,
    /// 因此 `rgb()` / `rgba()` 写不进样式里.
    Style,
}

/// 收集场景中的全部颜色字面量
fn color_literals(scene: &Scene) -> Vec<ColorLiteral> {
    scene
        .sentences()
        .iter()
        .enumerate()
        .flat_map(|(line, sentence)| {
            sentence_color_literals(sentence)
                .into_iter()
                .map(move |(span, color, syntax)| ColorLiteral {
                    line: line as u32,
                    span,
                    color,
                    syntax,
                })
        })
        .collect()
}

/// 收集单条语句中的颜色字面量 (行内字节区间)
fn sentence_color_literals(
    sentence: &SentenceInfo,
) -> Vec<(ops::Range<usize>, Color, ColorSyntax)> {
    let SentenceInfo {
        primary, sentence, ..
    } = sentence;
    let mut literals = Vec::new();

    // 语句参数, 形如 `-fontColor=rgba(0, 0, 0, 1)`
    for &(name, value) in &primary.arguments {
        let Some(value) = value.filter(|_| COLOR_ARGUMENTS.contains(&name)) else {
            continue;
        };
        // 与语句反序列化用同一个解析器: 报色块的取值一定也是合法取值
        let Some(color) = Color::from_str_rgba(value) else {
            continue;
        };
        literals.push((primary.get_span(value), color, ColorSyntax::Argument));
    }

    // 文本拓展样式, 形如 `[文字](style=color:#FF8800)`.
    // 只有对话内容支持文本拓展, 与 `webgal-simulate` 的解析一致.
    if let Some(content) = primary.content
        && matches!(sentence, Sentence::Say(_))
    {
        let offset = primary.get_span(content).start;
        for text in content.split('|') {
            for token in TokenSplit::new(text) {
                for (_, arguments) in &token.style {
                    for &(name, value) in arguments {
                        if !is_color_style(name) {
                            continue;
                        }
                        // 样式取值是标准 CSS 行内颜色
                        let Some(color) = parse_style_color(value) else {
                            continue;
                        };
                        let span = span_of(content, value);
                        literals.push((
                            offset + span.start..offset + span.end,
                            color,
                            ColorSyntax::Style,
                        ));
                    }
                }
            }
        }
    }

    literals
}

/// 是否为样式里的颜色属性
///
/// CSS 中以 `-color` 结尾的属性都取颜色值 (`color` / `background-color` / `border-color` ...).
fn is_color_style(name: &str) -> bool {
    name == "color" || name.ends_with("-color")
}

/// 解析文本样式里的颜色
///
/// 样式取值是标准 CSS 行内颜色, 因此除 [`Color`] 支持的 `#RRGGBB` / `rgb()` / `rgba()` 外,
/// 还接受 CSS Color 4 的 `#RRGGBBAA` —— 那是样式里唯一能表达透明度的写法
/// (带括号的 `rgb()` / `rgba()` 会被文本拓展语法的 `)` 截断, 见 [`ColorSyntax::Style`]).
fn parse_style_color(value: &str) -> Option<Color> {
    Color::from_str(value).ok().or_else(|| {
        let hex = value.trim().strip_prefix('#')?;
        // 先排除非 ASCII: 下面的按字节切片要求输入是单字节字符
        if hex.len() != 8 || !hex.is_ascii() {
            return None;
        }
        let parse = |range: ops::Range<usize>| u8::from_str_radix(&hex[range], 16).ok();
        Some(Color {
            red: parse(0..2)?,
            green: parse(2..4)?,
            blue: parse(4..6)?,
            alpha: f32::from(parse(6..8)?) / 255.,
        })
    })
}

// -------- 转换 --------

/// 生成颜色的规范写法
///
/// * 语句参数只接受 `rgba(R, G, B, A)`, 与语句反序列化的 `parse_color_css_rgba` 一致.
/// * 文本样式的取值不能含 `)` (文本拓展语法在第一个 `)` 处结束), 因此用 hex 表示:
///   不透明时是 `#RRGGBB`, 有透明度时是 CSS Color 4 的 `#RRGGBBAA`.
fn format_color(color: Color, syntax: ColorSyntax) -> String {
    let mut text = String::new();
    let result = match syntax {
        ColorSyntax::Argument => color.fmt_css_rgba(&mut text),
        ColorSyntax::Style => match alpha_byte(color) {
            u8::MAX => color.fmt_hex_upper(&mut text),
            alpha => write!(
                text,
                "#{:02X}{:02X}{:02X}{alpha:02X}",
                color.red, color.green, color.blue
            ),
        },
    };
    debug_assert!(result.is_ok(), "向字符串写入颜色不会失败");
    text
}

/// 颜色的透明度分量 (`[0, 255]`)
fn alpha_byte(color: Color) -> u8 {
    (color.alpha.clamp(0., 1.) * 255.).round() as u8
}

/// 转换为 LSP 颜色 (分量为 `[0, 1]` 浮点数)
fn to_lsp_color(color: Color) -> lsp_types::Color {
    lsp_types::Color {
        red: f32::from(color.red) / 255.,
        green: f32::from(color.green) / 255.,
        blue: f32::from(color.blue) / 255.,
        alpha: color.alpha,
    }
}

/// 从 LSP 颜色还原 (分量为 `[0, 1]` 浮点数)
///
/// # Behavior
/// * 颜色分量按字节取整.
/// * 透明度保留两位小数: 选择器给出的透明度是任意浮点数, 直接写进语句会变成
///   `rgba(0, 0, 0, 0.37254903)` 这样的长尾.
fn from_lsp_color(color: lsp_types::Color) -> Color {
    let component = |value: f32| (value.clamp(0., 1.) * 255.).round() as u8;
    Color {
        red: component(color.red),
        green: component(color.green),
        blue: component(color.blue),
        alpha: (color.alpha.clamp(0., 1.) * 100.).round() / 100.,
    }
}

/// 字面量的 LSP 区间 (UTF-8 行列)
fn literal_range(literal: &ColorLiteral) -> Range {
    Range {
        start: Position {
            line: literal.line,
            character: literal.span.start as u32,
        },
        end: Position {
            line: literal.line,
            character: literal.span.end as u32,
        },
    }
}

/// 判断两个区间是否重叠 (闭区间)
///
/// 颜色选择器会拿着上一次的区间连续请求: 文本被替换后区间未必与字面量严格相等,
/// 因此先按相等匹配, 退而按重叠匹配.
fn overlaps(span: &Range, other: Range) -> bool {
    span.start <= other.end && other.start <= span.end
}

